; ---- Subroutine: blitter.copy_rect ----
    ALIGN 2

blitter.copy_rect:
        movem.l d2-d7/a2-a6,-(sp)
        move.w  d0,d6           ; d6 = width
        move.w  d1,d7           ; d7 = height
        move.w  d2,d2           ; src_mod
        move.w  d3,d3           ; dst_mod
        bsr     .wait_blt
        tst.w   d5
        beq.s   .no_desc
        move.w  d6,d0
        lsl.w   #1,d0
        add.w   d2,d0
        move.w  d7,d1
        subq.w  #1,d1
        mulu.w  d0,d1
        move.w  d6,d0
        subq.w  #1,d0
        lsl.w   #1,d0
        ext.l   d0
        add.l   d0,d1
        add.l   d1,a0
        move.w  d6,d0
        lsl.w   #1,d0
        add.w   d3,d0
        move.w  d7,d1
        subq.w  #1,d1
        mulu.w  d0,d1
        move.w  d6,d0
        subq.w  #1,d0
        lsl.w   #1,d0
        ext.l   d0
        add.l   d0,d1
        add.l   d1,a1
.no_desc:
        move.w  d2,custom.BLTAMOD
        move.w  d3,custom.BLTDMOD
        move.w  #$ffff,custom.BLTAFWM
        move.w  #$ffff,custom.BLTALWM
        move.l  a0,custom.BLTAPT
        move.l  a1,custom.BLTDPT
        move.w  d4,d1
        or.w    #$0900,d1
        move.w  d1,custom.BLTCON0
        moveq   #0,d1
        tst.w   d5
        beq.s   .nodesc
        move.w  #$0002,d1
.nodesc:
        or.w    #$0800,d1       ; B32: AGA 32-bit blit mode
        move.w  d1,custom.BLTCON1
        move.w  d7,d1
        lsl.w   #6,d1
        or.w    d6,d1
        move.w  d1,custom.BLTSIZE
        movem.l (sp)+,d2-d7/a2-a6
        rts
.wait_blt:
        btst.b  #6,custom.DMACONR
        bne.s   .wait_blt
        rts
; End of subroutine: blitter.copy_rect


; ---- Subroutine: blitter.fill_rect ----
    ALIGN 2

blitter.fill_rect:
        movem.l d2-d7/a2-a6,-(sp)
        bsr     .wait_blt
        move.w  d3,custom.BLTDMOD
        move.w  #$ffff,custom.BLTAFWM
        move.w  #$ffff,custom.BLTALWM
        move.w  d2,custom.BLTCDAT
        move.l  a0,custom.BLTDPT
        move.w  #$01aa,custom.BLTCON0  ; USED=1, USEC=0, minterm=$AA (BLTCDAT -> D)
        move.w  #$0800,custom.BLTCON1 ; B32: AGA 32-bit blit mode
        move.w  d1,d1
        lsl.w   #6,d1
        or.w    d0,d1
        move.w  d1,custom.BLTSIZE
        movem.l (sp)+,d2-d7/a2-a6
        rts
.wait_blt:
        btst.b  #6,custom.DMACONR
        bne.s   .wait_blt
        rts
; End of subroutine: blitter.fill_rect


; ---- Subroutine: blitter.line_init ----
    ALIGN 2

blitter.line_init:
        movem.l d2-d7/a2-a6,-(sp)
        bsr     .wait_blt
        move.w  d0,custom.BLTAFWM
        move.w  #$ffff,custom.BLTALWM
        move.w  d1,custom.BLTADAT
        move.w  d2,custom.BLTBDAT
        move.w  d4,custom.BLTCMOD
        movem.l (sp)+,d2-d7/a2-a6
        rts
.wait_blt:
