; ---- Subroutine: math.crc16 ----
    ALIGN 2

math.crc16:
            move.w  d3,-(sp)
            move.w  d4,-(sp)
            lea     math.crc16_table,a1
            move.w  d1,d3           ; running crc = initvalue
.loop:
            subq.w  #1,d0
            bcs     .done
            move.w  d3,d1           ; copy crc
            lsr.w   #8,d1           ; index high byte
            move.b  (a0)+,d4        ; next data byte
            eor.b   d4,d1           ; table index
            lsl.w   #8,d3           ; crc <<= 8
            and.w   #$ff,d1
            add.w   d1,d1           ; word index
            move.w  (a1,d1.w),d1
            eor.w   d1,d3           ; update crc
            bra     .loop
.done:
            move.w  d3,d0
            eor.w   d2,d0           ; apply xorout
            move.w  (sp)+,d4
            move.w  (sp)+,d3
            rts
; End of subroutine: math.crc16


; ---- Subroutine: math.crc16_update ----
    ALIGN 2

math.crc16_update:
            lea     math.crc16_table,a0
            move.w  math.crc16_state,d1
            lsr.w   #8,d1           ; high byte of crc
            eor.b   d0,d1           ; table index
            move.w  math.crc16_state,d0
            lsl.w   #8,d0           ; crc <<= 8
            and.w   #$ff,d1
            add.w   d1,d1           ; word index
            move.w  (a0,d1.w),d1
            eor.w   d1,d0           ; new crc
            move.w  d0,math.crc16_state
            rts
; End of subroutine: math.crc16_update


; ---- Subroutine: math.crc32 ----
    ALIGN 2

math.crc32:
            move.l  d2,-(sp)
            lea     math.crc32_table,a1
            move.l  #$ffffffff,d1   ; running crc
.loop:
            subq.w  #1,d0
            bcs     .done
            move.b  (a0)+,d2        ; next data byte
            eor.b   d1,d2           ; table index = (crc ^ byte) & $ff
            lsr.l   #8,d1           ; crc >>= 8
            and.l   #$ff,d2
            lsl.l   #2,d2           ; long index
            move.l  (a1,d2.l),d2
            eor.l   d2,d1           ; update crc
            bra     .loop
.done:
            move.l  d1,d0
            eor.l   #$ffffffff,d0   ; final xor
            move.l  (sp)+,d2
            rts
; End of subroutine: math.crc32


; ---- Subroutine: math.crc32_update ----
    ALIGN 2

math.crc32_update:
            lea     math.crc32_table,a0
            move.l  math.crc32_state,d1
            eor.b   d1,d0           ; table index = (crc ^ byte) & $ff
            lsr.l   #8,d1           ; crc >>= 8
            and.l   #$ff,d0
            lsl.l   #2,d0           ; long index
            move.l  (a0,d0.l),d0
            eor.l   d0,d1           ; new crc
            move.l  d1,math.crc32_state
            rts
; End of subroutine: math.crc32_update


